-- SQLite Database Schema & Data Export
-- Generated on: 2026-07-05T23:36:11.535Z

PRAGMA foreign_keys = OFF;

-- 1. Create tables
CREATE TABLE IF NOT EXISTS equipment (
  id TEXT PRIMARY KEY,
  code TEXT,
  name TEXT,
  category TEXT,
  status TEXT,
  location TEXT,
  description TEXT,
  image_url TEXT,
  total_qty INTEGER,
  available_qty INTEGER CHECK(available_qty >= 0),
  maintenance_qty INTEGER,
  broken_qty INTEGER,
  created_at TEXT
);

CREATE TABLE IF NOT EXISTS borrow_requests (
  id TEXT PRIMARY KEY,
  requester_name TEXT,
  requester_company TEXT,
  requester_contact TEXT,
  items TEXT,
  purpose TEXT,
  requested_due_date TEXT,
  evidence_image_url TEXT,
  status TEXT,
  admin_note TEXT,
  reviewed_by TEXT,
  reviewed_at TEXT,
  transaction_ids TEXT,
  created_at TEXT,
  updated_at TEXT
);

CREATE TABLE IF NOT EXISTS transactions (
  id TEXT PRIMARY KEY,
  equipment_id TEXT,
  equipment_code TEXT,
  equipment_name TEXT,
  borrower_name TEXT,
  borrower_department TEXT,
  borrow_date TEXT,
  due_date TEXT,
  return_date TEXT,
  purpose TEXT,
  status TEXT,
  condition_on_return TEXT,
  created_at TEXT,
  borrow_qty INTEGER,
  evidence_image_url TEXT,
  condition_status TEXT,
  parent_tx_id TEXT
);

CREATE TABLE IF NOT EXISTS system_settings (
  id TEXT PRIMARY KEY,
  title TEXT,
  description TEXT,
  version TEXT,
  custom_logo TEXT,
  custom_pin TEXT,
  telegram_bot_token TEXT,
  telegram_chat_id TEXT,
  updated_at TEXT
);

-- Clear existing data (optional, to avoid duplicate keys)
DELETE FROM equipment;
DELETE FROM borrow_requests;
DELETE FROM transactions;
DELETE FROM system_settings;


